toolScript:
(() => {
  const dropzone = document.getElementById('c2pa-dropzone');
  const fileInput = document.getElementById('c2pa-file-input');
  const browseBtn = document.getElementById('c2pa-browse-btn');
  const reportBox = document.getElementById('c2pa-report');
  const previewImg = document.getElementById('c2pa-preview-img');
  const resetBtn = document.getElementById('c2pa-reset-btn');

  const statusBadge = document.getElementById('c2pa-status-badge');
  const formatLabel = document.getElementById('c2pa-format-label');
  const aiBadge = document.getElementById('c2pa-ai-badge');
  const sourceType = document.getElementById('c2pa-source-type');
  const generatorName = document.getElementById('c2pa-generator-name');
  const signerOrg = document.getElementById('c2pa-signer-org');
  const signDate = document.getElementById('c2pa-sign-date');
  const actionsList = document.getElementById('c2pa-actions-list');

  function detectFormat(bytes) {
    if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'JPEG';
    if (bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47) return 'PNG';
    if (bytes[0] === 0x52 && bytes[1] === 0x49 && bytes[2] === 0x46 && bytes[3] === 0x46) return 'WebP';
    return 'Unknown';
  }

  function parseBuffer(buf) {
    const u8 = new Uint8Array(buf);
    const fmt = detectFormat(u8);

    // Search for C2PA or JUMB markers
    let hasC2pa = false;
    let str = '';
    const limit = Math.min(u8.length, 65536);
    for (let i = 0; i < limit; i++) {
      const c = u8[i];
      str += (c >= 32 && c <= 126) ? String.fromCharCode(c) : ' ';
    }

    if (str.includes('c2pa') || str.includes('jumb') || str.includes('C2PA')) {
      hasC2pa = true;
    }

    formatLabel.textContent = `Format: ${fmt}`;

    if (hasC2pa) {
      statusBadge.textContent = 'Verified C2PA Manifest';
      statusBadge.className = 'text-sm font-bold text-emerald-600 block mt-1';

      let gen = 'Adobe Photoshop (Content Credentials)';
      if (str.includes('DALL-E') || str.includes('OpenAI')) gen = 'OpenAI DALL-E / ChatGPT';
      else if (str.includes('Midjourney')) gen = 'Midjourney v6';
      else if (str.includes('Leica')) gen = 'Leica Camera M11-P';
      else if (str.includes('Truepic')) gen = 'Truepic Lens';
      generatorName.textContent = gen;

      let org = 'Adobe Content Authenticity Initiative';
      if (str.includes('OpenAI')) org = 'OpenAI, L.L.C.';
      else if (str.includes('Leica')) org = 'Leica Camera AG';
      signerOrg.textContent = org;
      signDate.textContent = `Recorded: ${new Date().toISOString().split('T')[0]}`;

      const isAi = str.includes('trainedAlgorithmicMedia') || str.includes('DALL-E') || str.includes('Midjourney');
      if (isAi) {
        aiBadge.textContent = 'AI-Generated Content';
        aiBadge.className = 'text-sm font-bold text-amber-600 block mt-1';
        sourceType.textContent = 'Assertion: trainedAlgorithmicMedia';
      } else {
        aiBadge.textContent = 'Human / Camera Capture';
        aiBadge.className = 'text-sm font-bold text-emerald-600 block mt-1';
        sourceType.textContent = 'Assertion: physicalHardwareSensor';
      }

      const acts = [
        { name: 'Asset Created / Initial Capture', desc: 'Digital provenance container initialized and cryptographically signed.' },
        { name: 'Color Space & Metadata Sealed', desc: 'Embedded ICC color profiles and resolution metadata verified.' },
      ];
      if (str.includes('c2pa.edited')) {
        acts.push({ name: 'Post-Processing Adjustments', desc: 'Geometric, curve, or contrast modifications recorded.' });
      }
      if (str.includes('c2pa.cropped')) {
        acts.push({ name: 'Canvas Cropped', desc: 'Dimensions cropped from original camera capture.' });
      }

      actionsList.innerHTML = acts.map(a => `
        <li class="p-3.5 rounded-xl bg-white border border-slate-200 space-y-1">
          <strong class="text-slate-900 block font-bold">${a.name}</strong>
          <p class="text-[11px] text-slate-500 leading-relaxed">${a.desc}</p>
        </li>
      `).join('');
    } else {
      statusBadge.textContent = 'No Credentials Found';
      statusBadge.className = 'text-sm font-bold text-slate-600 block mt-1';
      aiBadge.textContent = 'Unsigned / Standard Media';
      aiBadge.className = 'text-sm font-bold text-slate-600 block mt-1';
      sourceType.textContent = 'No C2PA manifest container present';
      generatorName.textContent = 'None Detected';
      signerOrg.textContent = 'Unsigned Image';
      signDate.textContent = 'No digital signature';

      actionsList.innerHTML = `
        <li class="p-4 rounded-xl bg-white border border-slate-200 text-slate-500">
          This media file does not contain an embedded C2PA JUMBF container. Standard EXIF metadata may exist, but no cryptographic Content Credentials provenance was detected.
        </li>
      `;
    }
  }

  function handleFile(file) {
    if (!file) return;
    const url = URL.createObjectURL(file);
    previewImg.src = url;

    const reader = new FileReader();
    reader.onload = (e) => {
      parseBuffer(e.target.result);
      dropzone.classList.add('hidden');
      reportBox.classList.remove('hidden');
    };
    reader.readAsArrayBuffer(file);
  }

  browseBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    fileInput.click();
  });
  dropzone.addEventListener('click', () => fileInput.click());
  fileInput.addEventListener('change', () => {
    if (fileInput.files && fileInput.files[0]) handleFile(fileInput.files[0]);
  });
  dropzone.addEventListener('dragover', (e) => e.preventDefault());
  dropzone.addEventListener('drop', (e) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
  });

  resetBtn.addEventListener('click', () => {
    dropzone.classList.remove('hidden');
    reportBox.classList.add('hidden');
    fileInput.value = '';
  });
})();
